__email__ = "velocity.support@nokia.com"

import requests

import json
from velocity_communicator.log.log import Log
from velocity_communicator.support_services.private.external_methods import ExternalPrivates


class ExternalServices(ExternalPrivates):
    """

        Class with definition of external service methods. This class is
        inherited by main VelocityRestClient class.

        Services:
        make_request
        calient_optical_link_flap
        get_calient_information
        get_calient_sw_version
    """
    logger = Log.get_logger("velocityclient")

    def make_request(self, server, req_type, api_url, auth, data=""):
        header = {'Authorization': f'Basic {auth}',
                  'Content-Type': 'application/json'}
        url = f"{server}/{api_url}"
        return requests.request(req_type,
                                url=url,
                                headers=header,
                                data=data,
                                verify=False)

    def calient_optical_link_flap(self,
                                  calient_name: str,
                                  ports: list,
                                  lowperiod: str,
                                  highperiod: str,
                                  repeat: str,
                                  calient_info=""):
        """
        Endpoint to make link flap to port of calient.
        Calient sw version 6.4-1 onwards

        To Calient Node Configuration need set LINK_FLAP
        License and enable
        - REST Service
        - link flap

        To Calients properties need to define admin credentials to
        calientUsername or admin_username
        calientPassword or admin_password

        Before using, check that your environment have access to
        R&D Lab Network!

        calient_info:
        If need to call multible times link flap, you can get
        get_calient_information and pass it. Request is faster because
        calient information is not fetch every time

        return:
        [{'status': '200', 'msg': 'OK', 'description': 'Port Flap Initiated on port(s): x.x.x'}]

        :param calient_name: Calient inventory name in Velocity
        :type calient_name: str
        :param ports: Effected ports with string list. Max 10
        :type ports: [str]
        :param lowperiod: [milliseconds] : between 20ms and 30 min
        :type lowperiod: str
        :param highperiod: [milliseconds] : between 20ms and 30 min
        :type highperiod: str
        :param repeat: between 1 and 30
        :type repeat: str
        :param calient_info: responce of get_calient_information
        :type calient_info: dict
        """
        body = {"ports": ports,
                "lowperiod": lowperiod,
                "highperiod": highperiod,
                "repeat": repeat}

        if calient_info == "":
            calient_info = self.get_calient_information(calient_name)

        server = f'http://{calient_info["ip"]}'
        url = "rest/ports/?id=flap"
        req_type = "post"
        self.logger.info(f'{calient_name} ip is {calient_info["ip"]}')
        self.logger.info(f'Link flap request body: {body}')
        result = self.make_request(server=server,
                                   req_type=req_type,
                                   api_url=url,
                                   auth=calient_info["auth"],
                                   data=json.dumps(body, indent=4))
        print(f'Result was: {result}')
        return result.json()

    def get_calient_information(self, calient_name):
        """
        Return ip address and credentials as base64 encoded

        :param calient_name: Calient inventory name in Velocity
        :type calient_name: str
        :param calient_info: responce of get_calient_information
        :type calient_info: dict
        """
        device_info = self.get_devices(filter=f'name::{calient_name}')
        if device_info["total"] == 0 or device_info["total"] > 1:
            raise Exception("VC: Resource not found or there is multible devices!")
        username = ""
        password = ""
        calient_ip = ""
        for property in device_info["devices"][0]["properties"]:
            if property["name"] in ["ipAddress", "ip_address"]:
                calient_ip = property["value"]
            if property["name"] in ["calientUsername", "admin_username"]:
                username = property["value"]
            if property["name"] in ["calientPassword", "admin_password"]:
                password = property["value"]
        if username == "" or password == "":
            raise Exception(f'Admin credentials not defined to {calient_name} properties!')
        base_auth = self._get_base64_auth(username, password)
        return {"auth": base_auth, "ip": calient_ip}

    def get_calient_sw_version(self, calient_name, calient_info=""):
        """
        Return software version of given Calient

        From Calient Node Configuration need to enable
        - REST Service

        Before using, check that your environment have access to
        R&D Lab Network!

        :param calient_name: Calient inventory name in Velocity
        :type calient_name: str
        :param calient_info: responce of get_calient_information
        :type calient_info: dict
        """
        if calient_info == "":
            calient_info = self.get_calient_information(calient_name)
        server = f'http://{calient_info["ip"]}'
        url = "rest/info/?id=softwareversion"
        req_type = "get"
        result = self.make_request(server, req_type, url, calient_info["auth"])
        return result.json()
